fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both input vectors have the same length
    assert_eq!(
        a.len(),
        b.len(),
        "Input vectors must have the same length"
    );

    // Compare element-wise, converting each i8 to i32 before comparison
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| (x as i32) > (y as i32))
        .collect()
}

